replacements.new:
revision = decoded.revision if decoded.revision else "legacy"
if not report.applied_sections:
    skipped = ", ".join(report.skipped_sections) or "none"
    return onSelReturn(
        ok=f"No settings applied from revision {revision}; skipped sections: {skipped}."
    )
sections = ", ".join(report.applied_sections)
return onSelReturn(ok=f"Imported revision {revision}; sections: {sections}.")

replacements.old:
if not report.changed:
    return SettingsUpdateResult(
        False,
        decoded.revision,
        "Central settings are already current.",
        report.warnings,
    )

replacements.new:
if not report.changed:
    if report.skipped_sections:
        message = (
            f"Central settings revision {decoded.revision} was not applied; "
            "sections were skipped by local policy."
        )
    else:
        message = "Central settings are already current."
    return SettingsUpdateResult(
        False, decoded.revision, message, report.warnings
    )
